return-response.set-body:
@{
        JToken reqId;
        if (context.Variables.ContainsKey("mcpRequestId")) {
          long n;
          var rawId = (string)context.Variables["mcpRequestId"];
          reqId = long.TryParse(rawId, out n) ? (JToken)n : (JToken)rawId;
        } else {
          reqId = (JToken)"unknown";
        }
        var err = new JObject(
          new JProperty("jsonrpc", "2.0"),
          new JProperty("id", reqId),
          new JProperty("error", new JObject(
            new JProperty("code", -32603),
            new JProperty("message", context.LastError.Message)
          ))
        );
        return "data: " + err.ToString(Newtonsoft.Json.Formatting.None) + "\n\n";
      }
